{"command": "python3 << 'EOF'
import json

with open('/home/z16866199/Collect_trace/sft_eval/23_RepeatInterleave/23_RepeatInterleave.json.bak', 'r') as f:
    cases = [json.loads(line) for line in f if line.strip()]

# Select representative cases - target <= 10
selected = []
selected_indices = set()

def add_case(idx, reason):
    if idx not in selected_indices and idx < len(cases):
        selected_indices.add(idx)
        selected.append((idx, cases[idx], reason))

# 1. dtype coverage: float32, float16, bfloat16 (3 cases)
for dtype in ['float32', 'float16', 'bfloat16']:
    for i, case in enumerate(cases):
        if case['inputs'][0]['dtype'] == dtype:
            add_case(i, f"dtype={dtype}")
            break

# 2. ndim coverage: 1D, 2D, 3D, 4D - try to combine with uncovered dims
# 1D with dim=0 (already covered by dtype=float32 case 0)
# 2D with dim=1
for i, case in enumerate(cases):
    if len(case['inputs'][0]['shape']) == 2 and case['inputs'][2]['value'] == 1 and i not in selected_indices:
        add_case(i, "ndim=2,dim=1")
        break

# 3D with dim=2
for i, case in enumerate(cases):
    if len(case['inputs'][0]['shape']) == 3 and case['inputs'][2]['value'] == 2 and i not in selected_indices:
        add_case(i, "ndim=3,dim=2")
        break

# 4D with dim=3
for i, case in enumerate(cases):
    if len(case['inputs'][0]['shape']) == 4 and case['inputs'][2]['value'] == 3 and i not in selected_indices:
        add_case(i, "ndim=4,dim=3")
        break

# dim=-1
for i, case in enumerate(cases):
    if case['inputs'][2]['value'] == -1 and i not in selected_indices:
        add_case(i, "dim=-1")
        break

# 3. repeats=3 or 4 (not covered yet)
for i, case in enumerate(cases):
    if case['inputs'][1]['value'] in [3, 4] and i not in selected_indices:
        add_case(i, f"repeats={case['inputs'][1]['value']}")
        break

# 4. Max shape (extreme large)
max_elems = 0
max_idx = None
for i, case in enumerate(cases):
    shape = case['inputs'][0]['shape']
    total = 1
    for s in shape:
        total *= s
    if total > max_elems:
        max_elems = total
        max_idx = i
add_case(max_idx, "max_shape")

print(f"Selected {len(selected)} cases:")
for idx, case, reason in selected:
    shape = case['inputs'][0]['shape']
    dtype = case['inputs'][0]['dtype']
    repeats = case['inputs'][1]['value']
    dim = case['inputs'][2]['value']
    print(f"  [{idx}] {reason}: shape={shape}, dtype={dtype}, repeats={repeats}, dim={dim}")

# Write simplified JSON
with open('/home/z16866199/Collect_trace/sft_eval/23_RepeatInterleave/23_RepeatInterleave.json', 'w') as f:
    for idx, case, reason in selected:
        f.write(json.dumps(case) + '\n')

print(f"\nWritten {len(selected)} cases to simplified JSON")
EOF", "description": "Re-simplify to <= 10 cases"}

