13	// ============================================================
14	// 索引类算子 op_kernel 参考代码（单行更新 / index_select 风格）
15	// 适用: index_select, index_add 等 1D 共享索引算子
16	// 示例: 以 torch.index_select 为例
17	//       3D 布局: [outerSize, srcDimSize, innerSize]
18	//       index 为 1D 共享，每个 index 值选择一整行 innerSize 个元素
19	//       动态核分配: taskId 交错分配 outerIdx + indexRange
20	//       UB 级 Tiling: 小尾轴(≤4096)多行批量 / 大尾轴分块
21	// ============================================================
22	
23	#include "kernel_operator.h"
24	
25	using namespace AscendC;
26	
27	constexpr int64_t UB_CAPACITY = 192 * 1024;
28	constexpr int64_t MAX_CORES = 40;
29	constexpr int64_t MAX_INDEX_BATCH = 512;
30	constexpr int64_t SMALL_INNER_THRESHOLD = 4096;
31	constexpr int64_t BUFFER_NUM = 2;
32	
33	template <typename T>
34	class <OpName>Kernel {
35	public:
36	    __aicore__ inline <OpName>Kernel() {}
37	
38	    __aicore__ inline void Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
39	                                int64_t outerSize, int64_t innerSize,
40	                                int64_t indexSize, int64_t srcDimSize,
41	                                int64_t totalLength, int64_t coresPerOuter);
42	    __aicore__ inline void Process();
43	
44	private:
45	    __aicore__ inline void ProcessIndexRange(int64_t outerIdx,
46	                                              int64_t indexStart, int64_t indexEnd);
47	    __aicore__ inline void ProcessSmallInner(int64_t outerIdx,
48	                                              int64_t indexStart, int64_t indexEnd);
49	    __aicore__ inline void ProcessLargeInner(int64_t outerIdx,
50	                                              int64_t indexStart, int64_t indexEnd);
51	    __aicore__ inline void LoadIndexBatch(int64_t batchStart, int64_t batchSize);
52	    __aicore__ inline int32_t GetIndexValue(int64_t localIdx);
53	
54	private:
55	    TPipe pipe;
56	    TBuf<TPosition::VECCALC> indexBuf;                // 共享索引缓冲
57	    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;      // 双缓冲输出
58	
59	    GlobalTensor<T> inputGm;
60	    GlobalTensor<int32_t> indexGm;
61	    GlobalTensor<T> outputGm;
62	
63	    // 3D 维度
64	    int64_t outerSize_ = 0;
65	    int64_t innerSize_ = 0;
66	    int64_t indexSize_ = 0;
67	    int64_t srcDimSize_ = 0;
68	    int64_t coresPerOuter_ = 0;
69	    int64_t totalLength_ = 0;
70	
71	    // UB 级 Tiling 派生参数
72	    int64_t alignedInnerSize_ = 0;
73	    int64_t indexBatchSize_ = 0;
74	    int64_t tileSize_ = 0;
75	    int64_t alignedTileSize_ = 0;
76	    int64_t tileCount_ = 0;
77	    int64_t batchRows_ = 1;
78	    bool isSmallInner_ = false;
79	};
80	
81	// =========================== Init start ============================
82	
83	template <typename T>
84	__aicore__ inline void <OpName>Kernel<T>::Init(GM_ADDR input, GM_ADDR index, GM_ADDR output,
85	                                                int64_t outerSize, int64_t innerSize,
86	                                                int64_t indexSize, int64_t srcDimSize,
87	                                                int64_t totalLength, int64_t coresPerOuter) {
88	    outerSize_ = outerSize;
89	    innerSize_ = innerSize;
90	    indexSize_ = indexSize;
91	    srcDimSize_ = srcDimSize;
92	    totalLength_ = totalLength;
93	    coresPerOuter_ = coresPerOuter;
94	
95	    inputGm.SetGlobalBuffer((__gm__ T*)input, totalLength);
96	    indexGm.SetGlobalBuffer((__gm__ int32_t*)index);
97	    outputGm.SetGlobalBuffer((__gm__ T*)output);
98	
99	    // 对齐 innerSize（32 字节对齐）
100	    constexpr int64_t alignNum = 32 / sizeof(T);  // float32:8, float16/bf16:16
101	    alignedInnerSize_ = (innerSize_ + alignNum - 1) / alignNum * alignNum;
102	    if (alignedInnerSize_ == 0) alignedInnerSize_ = alignNum;
103	
104	    // 索引批次
105	    indexBatchSize_ = indexSize_ < MAX_INDEX_BATCH ? indexSize_ : MAX_INDEX_BATCH;
106	
107	    // 索引缓冲区大小（32 字节对齐）
108	    int64_t indexAlignedSize = (indexBatchSize_ * sizeof(int32_t) + 31) / 32 * 32;
109	    pipe.InitBuffer(indexBuf, indexAlignedSize);
110	
111	    // 可用 UB 空间（减去 indexBuf）
112	    int64_t availableUB = UB_CAPACITY - indexAlignedSize;
113	    int64_t maxElementsInUB = availableUB / sizeof(T) / BUFFER_NUM;
114	
115	    // 小尾轴 / 大尾轴判断
116	    isSmallInner_ = (innerSize_ <= SMALL_INNER_THRESHOLD);
117	
118	    if (isSmallInner_) {
119	        // 小尾轴: 多行批量处理
120	        int64_t maxRows = maxElementsInUB / alignedInnerSize_;
121	        batchRows_ = maxRows < indexBatchSize_ ? maxRows : indexBatchSize_;
122	        if (batchRows_ < 1) batchRows_ = 1;
123	
124	        tileSize_ = innerSize_;
125	        alignedTileSize_ = alignedInnerSize_;
126	        tileCount_ = 1;
127	    } else {
128	        // 大尾轴: 分块处理
129	        if (alignedInnerSize_ > maxElementsInUB) {
130	            tileSize_ = maxElementsInUB / alignNum * alignNum;
131	            alignedTileSize_ = tileSize_;
132	            tileCount_ = (innerSize_ + tileSize_ - 1) / tileSize_;
133	        } else {
134	            tileSize_ = innerSize_;
135	            alignedTileSize_ = alignedInnerSize_;
136	            tileCount_ = 1;
137	        }
138	        batchRows_ = 1;
139	    }
140	
141	    pipe.InitBuffer(outQueue, BUFFER_NUM, alignedTileSize_ * sizeof(T) * batchRows_);
142	}
