149	template <typename T>
150	__aicore__ inline void <OpName>Kernel<T>::LoadIndexBatch(int64_t batchStart, int64_t batchSize) {
151	    LocalTensor<int32_t> indexLocal = indexBuf.Get<int32_t>();
152	
153	    DataCopyExtParams copyParams;
154	    copyParams.blockCount = 1;
155	    copyParams.blockLen = static_cast<uint32_t>(batchSize * sizeof(int32_t));
156	    copyParams.srcStride = 0;
157	    copyParams.dstStride = 0;
158	
159	    DataCopyPadExtParams<int32_t> padParams;
160	    padParams.isPad = false;
161	
162	    DataCopyPad(indexLocal, indexGm[batchStart], copyParams, padParams);
163	    PipeBarrier<PIPE_ALL>();
164	}
