#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class RepeatInterleaveKernel {
public:
    __aicore__ inline RepeatInterleaveKernel() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                int64_t outerSize, int64_t dimSize, int64_t innerSize,
                                int64_t repeats, int64_t tileLength);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t srcOffset, int64_t len);
    __aicore__ inline void CopyOut(int64_t dstOffset, int64_t len);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;

    GlobalTensor<T> xGm;
    GlobalTensor<T> yGm;

    int64_t outerSize_ = 0;
    int64_t dimSize_ = 0;
    int64_t innerSize_ = 0;
    int64_t repeats_ = 0;
    int64_t tileLength_ = 0;
};

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::Init(GM_ADDR x, GM_ADDR y,
                                                        int64_t outerSize, int64_t dimSize, int64_t innerSize,
                                                        int64_t repeats, int64_t tileLength) {
    outerSize_ = outerSize;
    dimSize_ = dimSize;
    innerSize_ = innerSize;
    repeats_ = repeats;
    tileLength_ = tileLength;

    int64_t xTotalLen = outerSize_ * dimSize_ * innerSize_;
    int64_t yTotalLen = outerSize_ * dimSize_ * repeats_ * innerSize_;
    xGm.SetGlobalBuffer((__gm__ T*)x, xTotalLen);
    yGm.SetGlobalBuffer((__gm__ T*)y, yTotalLen);

    pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength_ * sizeof(T));
    pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength_ * sizeof(T));
}

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::CopyIn(int64_t srcOffset, int64_t len) {
    LocalTensor<T> xLocal = inQueue.AllocTensor<T>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPadExtParams<T> padParams;
    padParams.isPad = false;
    DataCopyPad(xLocal, xGm[srcOffset], copyParams, padParams);
    inQueue.EnQue(xLocal);
}

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::CopyOut(int64_t dstOffset, int64_t len) {
    LocalTensor<T> xLocal = inQueue.DeQue<T>();
    LocalTensor<T> yLocal = outQueue.AllocTensor<T>();
    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;
    DataCopyPad(yLocal, xLocal, copyParams);
    outQueue.EnQue<T>(yLocal);

    LocalTensor<T> outLocal = outQueue.DeQue<T>();
    DataCopyPad(yGm[dstOffset], outLocal, copyParams);
    outQueue.FreeTensor(outLocal);
    inQueue.FreeTensor(xLocal);
}

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::Process() {
    int64_t blockIdx = GetBlockIdx();
    int64_t coreNum = GetBlockNum();

    int64_t outerPerCore = (outerSize_ + coreNum - 1) / coreNum;
    int64_t outerStart = blockIdx * outerPerCore;
    int64_t outerEnd = outerStart + outerPerCore;
    if (outerEnd > outerSize_) outerEnd = outerSize_;

    int64_t tileNum = (innerSize_ + tileLength_ - 1) / tileLength_;
    int64_t tailTileLength = innerSize_ - (tileNum - 1) * tileLength_;

    for (int64_t outer = outerStart; outer < outerEnd; ++outer) {
        for (int64_t d = 0; d < dimSize_; ++d) {
            int64_t srcOffset = outer * dimSize_ * innerSize_ + d * innerSize_;

            for (int64_t t = 0; t < tileNum; ++t) {
                int64_t curTileLength = (t == tileNum - 1) ? tailTileLength : tileLength_;
                int64_t tileStart = t * tileLength_;

                CopyIn(srcOffset + tileStart, curTileLength);

                for (int64_t r = 0; r < repeats_; ++r) {
                    int64_t dstOffset = outer * dimSize_ * repeats_ * innerSize_
                                      + (d * repeats_ + r) * innerSize_ + tileStart;
                    CopyOut(dstOffset, curTileLength);
                }
            }
        }
    }
}

extern "C" __global__ __aicore__ void repeat_interleave(GM_ADDR x, GM_ADDR y,
                                                          int64_t outerSize, int64_t dimSize, int64_t innerSize,
                                                          int64_t repeats, int64_t tileLength) {
    if (outerSize * dimSize * innerSize > 0) {
        RepeatInterleaveKernel<half> op;
        op.Init(x, y, outerSize, dimSize, innerSize, repeats, tileLength);
        op.Process();
    }
}
