143	template <typename T>
144	__aicore__ inline void RepeatInterleaveKernel<T>::Process() {
145	    int64_t blockIdx = GetBlockIdx();
146	
147	    // 计算当前核处理的 outer 范围
148	    int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
149	    int64_t coreOffset = (blockIdx < formerNum_) ?
150	                         blockIdx * formerLength_ :
151	                         formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;
152	
153	    if (coreOffset >= batch_) return;
154	    if (coreOffset + coreLength > batch_) {
155	        coreLength = batch_ - coreOffset;
156	    }
157	
158	    int64_t inputRowSize = dimSize_ * innerSize_;
159	    int64_t outputRowSize = outputDimSize_ * innerSize_;
160	
161	    // 计算 tile 数量（沿 innerSize 维度分块）
162	    int64_t tileNum = (innerSize_ + tileLength_ - 1) / tileLength_;
163	    int64_t tailTileLength = innerSize_ - (tileNum - 1) * tileLength_;
164	
165	    for (int64_t b = 0; b < coreLength; ++b) {
166	        int64_t outerIdx = coreOffset + b;
167	
168	        for (int64_t d = 0; d < dimSize_; ++d) {
169	            // 输入偏移: outerIdx * dimSize * innerSize + d * innerSize
170	            int64_t inputBase = outerIdx * inputRowSize + d * innerSize_;
171	            // 输出偏移: outerIdx * outputDimSize * innerSize + d * repeats * innerSize
172	            int64_t outputBase = outerIdx * outputRowSize + d * repeats_ * innerSize_;
173	
174	            for (int64_t t = 0; t < tileNum; ++t) {
175	                int64_t curTileLength = (t == tileNum - 1) ? tailTileLength : tileLength_;
176	                int64_t tileStart = t * tileLength_;
177	
178	                int64_t srcOffset = inputBase + tileStart;
179	                int64_t copyLen = curTileLength;
180	
181	                // CopyIn: 从 GM 读取数据到 UB
182	                CopyIn(srcOffset, copyLen);
183	
184	                // 从 inQueue 取出数据，重复 repeats 次写入 outQueue
185	                LocalTensor<T> inLocal = inQueue.DeQue<T>();
186	
187	                for (int64_t r = 0; r < repeats_; ++r) {
188	                    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();
189	
190	                    // 将 inLocal 复制到 outLocal (UB -> UB, 使用 DataCopy)
191	                    DataCopy(outLocal, inLocal, static_cast<uint32_t>(copyLen));
192	                    outQueue.EnQue(outLocal);
193	
194	                    // CopyOut: 写回 GM
195	                    int64_t dstOffset = outputBase + r * innerSize_ + tileStart;
196	                    CopyOut(dstOffset, copyLen);
197	                }
198	
199	                inQueue.FreeTensor(inLocal);
200	            }
201	        }
202	    }
203	}
