24	struct RepeatInterleaveTiling {
25	    int64_t outerSize;
26	    int64_t dimSize;
27	    int64_t innerSize;
28	    int64_t repeats;
29	    int64_t formerNum;
30	    int64_t formerLength;
31	    int64_t tailNum;
32	    int64_t tailLength;
33	    int64_t tileLength;
34	};
35	
36	at::Tensor repeat_interleave(const at::Tensor &self, int64_t repeats, int64_t dim) {
37	    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
38	                "repeat_interleave: input must be on NPU device");
39	    TORCH_CHECK(repeats >= 0, "repeat_interleave: repeats must be non-negative, got ", repeats);
40	
41	    int64_t ndim = self.dim();
42	    if (dim < 0) dim += ndim;
43	    TORCH_CHECK(dim >= 0 && dim < ndim,
44	                "repeat_interleave: dim out of range, got dim=", dim, " but ndim=", ndim);
45	
46	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
47	                self.scalar_type() == at::kHalf ||
48	                self.scalar_type() == at::kBFloat16,
49	                "repeat_interleave: only float32, float16 and bfloat16 are supported");
50	
51	    at::Tensor selfContiguous = self.contiguous();
52	
53	    // Compute output shape
54	    auto outputShape = selfContiguous.sizes().vec();
55	    outputShape[dim] *= repeats;
56	    auto output = at::empty(outputShape, selfContiguous.options());
57	
58	    if (self.numel() == 0 || repeats == 0) {
59	        return output;
60	    }
61	
62	    // 3D dimension decomposition:
63	    // outerSize = product of dims before dim
64	    // dimSize = size of dim dimension
65	    // innerSize = product of dims after dim
66	    int64_t outerSize = 1;
67	    for (int64_t i = 0; i < dim; ++i) {
68	        outerSize *= selfContiguous.size(i);
69	    }
70	    int64_t dimSize = selfContiguous.size(dim);
71	    int64_t innerSize = 1;
72	    for (int64_t i = dim + 1; i < ndim; ++i) {
73	        innerSize *= selfContiguous.size(i);
74	    }
75	
76	    int64_t dtypeSize = selfContiguous.element_size();
77	
78	    // Platform API
79	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
80	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
81	    uint64_t ubSize;
82	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
83	
84	    // Block-level tiling: divide by outerSize
85	    int64_t usedCoreNum = outerSize < coreNum ? outerSize : coreNum;
86	    if (usedCoreNum < 1) usedCoreNum = 1;
87	
88	    int64_t formerNum = usedCoreNum - 1;
89	    int64_t tailNum = 1;
90	    int64_t formerLength = (outerSize + usedCoreNum - 1) / usedCoreNum;
91	    int64_t tailLength = outerSize - formerNum * formerLength;
92	    if (tailLength < 0) {
93	        tailLength = formerLength;
94	        formerNum = usedCoreNum;
95	        tailNum = 0;
96	    }
97	
98	    // UB-level tiling
99	    int64_t bufferCoefficient = (dtypeSize == 4) ? 20 : 16;
100	    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient;
101	    int64_t alignElements = 32 / dtypeSize;
102	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
103	    if (tileLength < alignElements) tileLength = alignElements;
104	    if (tileLength > innerSize) tileLength = innerSize;
105	    if (tileLength < 1) tileLength = 1;
106	    // Ensure tileLength is aligned to 32 bytes
107	    tileLength = (tileLength / alignElements) * alignElements;
108	    if (tileLength < 1) tileLength = alignElements;
109	
110	    // Create tiling tensor on CPU
111	    int64_t tilingSize = static_cast<int64_t>(sizeof(RepeatInterleaveTiling));
112	    at::Tensor tilingCpu = at::empty(at::IntArrayRef({tilingSize}),
113	                                     at::device(at::kCPU).dtype(at::kByte));
114	    auto *tiling = reinterpret_cast<RepeatInterleaveTiling *>(tilingCpu.data_ptr());
115	    tiling->outerSize = outerSize;
116	    tiling->dimSize = dimSize;
117	    tiling->innerSize = innerSize;
118	    tiling->repeats = repeats;
119	    tiling->formerNum = formerNum;
120	    tiling->formerLength = formerLength;
121	    tiling->tailNum = tailNum;
122	    tiling->tailLength = tailLength;
123	    tiling->tileLength = tileLength;
124	
125	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
126	
127	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
128	    if (blockDim < 1) blockDim = 1;
129	
130	    bool isFp16 = (self.scalar_type() == at::kHalf || self.scalar_type() == at::kBFloat16);
131	    if (isFp16) {
132	        EXEC_KERNEL_CMD(repeat_interleave_fp16, blockDim,
133	                        selfContiguous, output, tilingNpu);
134	    } else {
135	        EXEC_KERNEL_CMD(repeat_interleave_fp32, blockDim,
136	                        selfContiguous, output, tilingNpu);
137	    }
138	
139	    return output;
140	}
