#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_repeat_interleave_fp16.h"
#include "aclrtlaunch_repeat_interleave_fp32.h"
#include <torch/extension.h>

namespace ascend_kernel {

struct RepeatInterleaveTiling {
    int64_t outerSize;
    int64_t dimSize;
    int64_t innerSize;
    int64_t repeats;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
};

at::Tensor repeat_interleave(const at::Tensor &self, int64_t repeats, int64_t dim) {
    TORCH_CHECK(self.device().type() == at::DeviceType::PrivateUse1,
                "repeat_interleave: input must be on NPU device");
    TORCH_CHECK(repeats >= 0, "repeat_interleave: repeats must be non-negative, got ", repeats);

    int64_t ndim = self.dim();
    if (dim < 0) dim += ndim;
    TORCH_CHECK(dim >= 0 && dim < ndim,
                "repeat_interleave: dim out of range, got dim=", dim, " but ndim=", ndim);

    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "repeat_interleave: only float32, float16 and bfloat16 are supported");

    at::Tensor selfContiguous = self.contiguous();

    // If dim is not 0, transpose dim to position 0 so kernel can treat it uniformly
    at::Tensor inputForKernel;
    std::vector<int64_t> permuteOrder;
    bool needTranspose = (dim != 0);
    if (needTranspose) {
        permuteOrder.reserve(ndim);
        permuteOrder.push_back(dim);
        for (int64_t i = 0; i < ndim; ++i) {
            if (i != dim) permuteOrder.push_back(i);
        }
        inputForKernel = selfContiguous.permute(permuteOrder).contiguous();
    } else {
        inputForKernel = selfContiguous;
    }

    // Compute output shape: dimSize * repeats
    auto outputShape = inputForKernel.sizes().vec();
    outputShape[0] *= repeats;
    auto output = at::empty(outputShape, inputForKernel.options());

    if (self.numel() == 0 || repeats == 0) {
        return output;
    }

    // After transpose, input is [dimSize, rest...]
    // We treat this as 3D: [outerSize=1, dimSize, innerSize=rest]
    int64_t dimSize = inputForKernel.size(0);
    int64_t innerSize = inputForKernel.numel() / dimSize;
    int64_t outerSize = 1;

    int64_t dtypeSize = inputForKernel.element_size();

    // Platform API
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);

    // Block-level tiling: divide by dimSize (each core handles some "slices" along dim 0)
    int64_t usedCoreNum = dimSize < coreNum ? dimSize : coreNum;
    if (usedCoreNum < 1) usedCoreNum = 1;

    int64_t formerNum = usedCoreNum - 1;
    int64_t tailNum = 1;
    int64_t formerLength = (dimSize + usedCoreNum - 1) / usedCoreNum;
    int64_t tailLength = dimSize - formerNum * formerLength;
    if (tailLength < 0) {
