    int64_t maxTileElements = static_cast<int64_t>(ubSize) / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength < alignElements) tileLength = alignElements;
    if (tileLength > innerSize) tileLength = innerSize;
    if (tileLength < 1) tileLength = 1;
    tileLength = (tileLength / alignElements) * alignElements;
    if (tileLength < 1) tileLength = alignElements;

    // Create tiling tensor on CPU
    int64_t tilingSize = static_cast<int64_t>(sizeof(RepeatInterleaveTiling));
    at::Tensor tilingCpu = at::empty(at::IntArrayRef({tilingSize}),
                                     at::device(at::kCPU).dtype(at::kByte));
    auto *tiling = reinterpret_cast<RepeatInterleaveTiling *>(tilingCpu.data_ptr());
    tiling->outerSize = outerSize;
    tiling->dimSize = dimSize;
    tiling->innerSize = innerSize;
    tiling->repeats = repeats;
    tiling->formerNum = formerNum;
    tiling->formerLength = formerLength;
    tiling->tailNum = tailNum;
    tiling->tailLength = tailLength;
    tiling->tileLength = tileLength;

    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    if (blockDim < 1) blockDim = 1;

    bool isFp16 = (inputForKernel.scalar_type() == at::kHalf || inputForKernel.scalar_type() == at::kBFloat16);
    if (isFp16) {
        EXEC_KERNEL_CMD(repeat_interleave_fp16, blockDim,
                        inputForKernel, output, tilingNpu);
    } else {
        EXEC_KERNEL_CMD(repeat_interleave_fp32, blockDim,
                        inputForKernel, output, tilingNpu);
    }

    // If we transposed, need to transpose back
    if (needTranspose) {
        // Create inverse permutation
        std::vector<int64_t> inversePermute(ndim);
        for (int64_t i = 0; i < ndim; ++i) {
            inversePermute[permuteOrder[i]] = i;
        }
        output = output.permute(inversePermute).contiguous();
    }

    return output;
}

