// ============================================================
// repeat_interleave op_kernel
// 适用: torch.repeat_interleave(self, repeats, dim)
// 将输入沿 dim 维度的每个元素重复 repeats 次
// 本质: 纯数据搬运操作，使用 DataCopyPad 实现
//
// 设计: 按 dim 分核，每个核处理一段连续的 dim。
//       对于每个 dim，读取 innerSize 个元素，重复 repeats 次写入输出。
//       当 innerSize 很小时，将多个 dim 合并搬运，确保每次搬运 >= 32B。
// ============================================================

#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t BUFFER_NUM = 2;

struct RepeatInterleaveTiling {
    int64_t outerSize;
    int64_t dimSize;
    int64_t innerSize;
    int64_t repeats;
    int64_t formerNum;
    int64_t formerLength;
    int64_t tailNum;
    int64_t tailLength;
    int64_t tileLength;
};

template <typename T>
class RepeatInterleaveKernel {
public:
    __aicore__ inline RepeatInterleaveKernel() {}

    __aicore__ inline void Init(GM_ADDR self, GM_ADDR output, GM_ADDR tiling);
    __aicore__ inline void Process();

private:
    __aicore__ inline void CopyIn(int64_t srcOffset, int64_t len);
    __aicore__ inline void CopyOut(int64_t dstOffset, int64_t len);

private:
    TPipe pipe;
    TQue<TPosition::VECIN, BUFFER_NUM> inQueue;
    TQue<TPosition::VECOUT, BUFFER_NUM> outQueue;

    GlobalTensor<T> selfGm;
    GlobalTensor<T> outputGm;

    int64_t batch_ = 0;
    int64_t dimSize_ = 0;
    int64_t innerSize_ = 0;
    int64_t repeats_ = 0;
    int64_t outputDimSize_ = 0;

    int64_t formerNum_ = 0;
    int64_t formerLength_ = 0;
    int64_t tailNum_ = 0;
    int64_t tailLength_ = 0;
    int64_t tileLength_ = 0;
};

// =========================== Init start ============================

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::Init(GM_ADDR self, GM_ADDR output, GM_ADDR tiling) {
    // 读取 tiling 参数
    auto *tilingData = reinterpret_cast<__gm__ RepeatInterleaveTiling*>(tiling);
    batch_ = tilingData->outerSize;
    dimSize_ = tilingData->dimSize;
    innerSize_ = tilingData->innerSize;
    repeats_ = tilingData->repeats;
    formerNum_ = tilingData->formerNum;
    formerLength_ = tilingData->formerLength;
    tailNum_ = tilingData->tailNum;
    tailLength_ = tilingData->tailLength;
    tileLength_ = tilingData->tileLength;
    outputDimSize_ = dimSize_ * repeats_;

    int64_t totalInputLength = batch_ * dimSize_ * innerSize_;
    int64_t totalOutputLength = batch_ * outputDimSize_ * innerSize_;

    selfGm.SetGlobalBuffer((__gm__ T*)self, totalInputLength);
    outputGm.SetGlobalBuffer((__gm__ T*)output, totalOutputLength);

    // 输入 buffer: 搬运 tileLength 个元素
    pipe.InitBuffer(inQueue, BUFFER_NUM, tileLength_ * sizeof(T));
    // 输出 buffer: 搬运 tileLength 个元素
    pipe.InitBuffer(outQueue, BUFFER_NUM, tileLength_ * sizeof(T));
}

// =========================== Init end ============================

// =========================== CopyIn start ============================

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::CopyIn(int64_t srcOffset, int64_t len) {
    LocalTensor<T> inLocal = inQueue.AllocTensor<T>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;

    DataCopyPadExtParams<T> padParams;
    padParams.isPad = false;

    DataCopyPad(inLocal, selfGm[srcOffset], copyParams, padParams);
    inQueue.EnQue(inLocal);
}

// =========================== CopyIn end ============================

// =========================== CopyOut start ============================

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::CopyOut(int64_t dstOffset, int64_t len) {
    LocalTensor<T> outLocal = outQueue.DeQue<T>();

    DataCopyExtParams copyParams;
    copyParams.blockCount = 1;
    copyParams.blockLen = static_cast<uint32_t>(len * sizeof(T));
    copyParams.srcStride = 0;
    copyParams.dstStride = 0;

    DataCopyPad(outputGm[dstOffset], outLocal, copyParams);
    outQueue.FreeTensor(outLocal);
}

// =========================== CopyOut end ============================

// =========================== Process start ============================

template <typename T>
__aicore__ inline void RepeatInterleaveKernel<T>::Process() {
    int64_t blockIdx = GetBlockIdx();

    // 计算当前核处理的 dim 范围
    int64_t coreLength = (blockIdx < formerNum_) ? formerLength_ : tailLength_;
    int64_t coreOffset = (blockIdx < formerNum_) ?
                         blockIdx * formerLength_ :
                         formerNum_ * formerLength_ + (blockIdx - formerNum_) * tailLength_;

    if (coreOffset >= dimSize_) return;
    if (coreOffset + coreLength > dimSize_) {
        coreLength = dimSize_ - coreOffset;
    }

    int64_t inputRowSize = dimSize_ * innerSize_;
    int64_t outputRowSize = outputDimSize_ * innerSize_;

    // 计算 tile 数量（沿 innerSize 维度分块）
    int64_t tileNum = (innerSize_ + tileLength_ - 1) / tileLength_;
    int64_t tailTileLength = innerSize_ - (tileNum - 1) * tileLength_;

    for (int64_t b = 0; b < batch_; ++b) {
        int64_t outerIdx = b;

        for (int64_t dOffset = 0; dOffset < coreLength; ++dOffset) {
            int64_t d = coreOffset + dOffset;

            // 输入偏移: outerIdx * dimSize * innerSize + d * innerSize
            int64_t inputBase = outerIdx * inputRowSize + d * innerSize_;
            // 输出偏移: outerIdx * outputDimSize * innerSize + d * repeats * innerSize
            int64_t outputBase = outerIdx * outputRowSize + d * repeats_ * innerSize_;

            for (int64_t t = 0; t < tileNum; ++t) {
                int64_t curTileLength = (t == tileNum - 1) ? tailTileLength : tileLength_;
                int64_t tileStart = t * tileLength_;

                int64_t srcOffset = inputBase + tileStart;
                int64_t copyLen = curTileLength;

                // CopyIn: 从 GM 读取数据到 UB
                CopyIn(srcOffset, copyLen);

                // 从 inQueue 取出数据
                LocalTensor<T> inLocal = inQueue.DeQue<T>();

                for (int64_t r = 0; r < repeats_; ++r) {
                    LocalTensor<T> outLocal = outQueue.AllocTensor<T>();

                    // 将 inLocal 复制到 outLocal (UB -> UB, 使用 DataCopy)
                    DataCopy(outLocal, inLocal, static_cast<uint32_t>(copyLen));
                    outQueue.EnQue<T>(outLocal);

                    // CopyOut: 写回 GM
                    int64_t dstOffset = outputBase + r * innerSize_ + tileStart;
                    CopyOut(dstOffset, copyLen);
                }

                inQueue.FreeTensor(inLocal);
            }
        }
    }
}

// =========================== Process end ============================

// =========================== Kernel 入口 start ============================

extern "C" __global__ __aicore__ void repeat_interleave_fp16(GM_ADDR self, GM_ADDR output, GM_ADDR tiling) {
    if (tiling != nullptr) {
        RepeatInterleaveKernel<half> op;
        op.Init(self, output, tiling);
        op.Process();
    }
}

extern "C" __global__ __aicore__ void repeat_interleave_fp32(GM_ADDR self, GM_ADDR output, GM_ADDR tiling) {
    if (tiling != nullptr) {
        RepeatInterleaveKernel<float> op;
        op.Init(self, output, tiling);
        op.Process();
    }
}

